package cn.iocoder.txgy.module.erp.service.sale.listener;
import cn.iocoder.txgy.module.bpm.api.event.*; import cn.iocoder.txgy.module.erp.enums.ApiConstants; import cn.iocoder.txgy.module.erp.service.sale.*; import jakarta.annotation.Resource; import org.springframework.web.bind.annotation.*;
@RestController public class ErpCostResultStatusListener extends BpmProcessInstanceStatusEventListener { @Resource private ErpCostResultService service; @Override protected String getProcessDefinitionKey(){return ErpCostResultServiceImpl.BPM_PROCESS_DEFINITION_KEY;} @Override @PostMapping(ApiConstants.PREFIX+"/cost-result/update-audit-status") protected void onEvent(@RequestBody BpmProcessInstanceStatusEvent e){service.updateAuditStatus(Long.parseLong(e.getBusinessKey()),e.getStatus());} }
